create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Assertion failed: %',label;end if;end$$;
create function pg_temp.reject(query text,expected text) returns void language plpgsql as $$begin execute query; raise exception 'Unexpected success'; exception when others then if sqlerrm<>expected then raise;end if;end$$;
insert into professional_profiles values ('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002');
insert into patients values('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001',null,'SYNTHETIC',null,null);
insert into consultations values('20000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',null,'draft');
insert into consultation_snapshots(professional_id,consultation_id,patient_id,revision,structure,clinical_records)
  select professional_id,id,patient_id,1,'{"consultation_type":"follow_up","sections":[{"section_key":"personal","title":"Personal","questions":[{"question_key":"next_objectives","label":"Mi objetivo personalizado","question_type":"long_text","response_area":"professional_assessment","is_required":false,"configuration":{}}]}]}',
  '{"recall":{"approved_at":"2026-10-12","narrative":"Texto previo","items":[]}}' from consultations;
update consultation_snapshots set clinical_records='{"recall":{"approved_at":"2026-10-12","narrative":"Texto previo","items":[]}}';
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
set local role authenticated;
select (public.prepare_consultation_workflow('20000000-0000-0000-0000-000000000001',1)).revision;
reset role;
select pg_temp.assert_true((select structure#>>'{sections,0,questions,0,label}'='Mi objetivo personalizado' from consultation_snapshots),'custom question preserved');
select pg_temp.assert_true((select clinical_records->'recall'->>'narrative'='Texto previo' from consultation_snapshots),'existing recall preserved');
select pg_temp.assert_true((select revision=1 from consultation_snapshots),'same answer and clinical revision');
select pg_temp.assert_true((select count(*)=1 from consultation_snapshots s cross join lateral jsonb_array_elements(s.structure->'sections') sec cross join lateral jsonb_array_elements(sec->'questions') q where q->>'question_key'='next_objectives'),'no duplicate objective');
select pg_temp.assert_true((select count(*)=1 from consultation_snapshots s cross join lateral jsonb_array_elements(s.structure->'sections') sec cross join lateral jsonb_array_elements(sec->'questions') q where q->>'question_key'='recall_24h_v2'),'follow-up recall available');
select pg_temp.assert_true((select count(*)=1 from consultation_snapshots s cross join lateral jsonb_array_elements(s.structure->'sections') sec cross join lateral jsonb_array_elements(sec->'questions') q where q->>'question_key'='pes_statement'),'follow-up PES available');
select pg_temp.assert_true((select private.with_consultation_workflow(structure)=structure from consultation_snapshots),'idempotent');
select public.save_consultation_responses('20000000-0000-0000-0000-000000000001',1,'{"recall_24h_v2":[{"food":"Huevo"}],"first_actions":"Acuerdo revisado"}');
select pg_temp.assert_true((select value='[{"food":"Huevo"}]' from consultation_answers where question_key='recall_24h_v2'),'new recall answers persist through existing save RPC');
select pg_temp.assert_true((select value='"Acuerdo revisado"' from consultation_answers where question_key='first_actions'),'existing instruction key is retained');
set local role authenticated;
select pg_temp.reject($q$select public.prepare_consultation_workflow('20000000-0000-0000-0000-000000000001',2)$q$,'context_changed');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
select pg_temp.reject($q$select public.prepare_consultation_workflow('20000000-0000-0000-0000-000000000001',1)$q$,'context_unavailable');
set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
set local test.block_write='true';
select pg_temp.reject($q$select public.prepare_consultation_workflow('20000000-0000-0000-0000-000000000001',1)$q$,'feature_denied');
set local test.block_write='false';
reset role;
update consultations set status='completed';
set local role authenticated;
select pg_temp.reject($q$select public.prepare_consultation_workflow('20000000-0000-0000-0000-000000000001',1)$q$,'context_unavailable');
reset role;
select pg_temp.assert_true(not has_function_privilege('anon','public.prepare_consultation_workflow(uuid,integer)','execute'),'anonymous access denied');
select pg_temp.assert_true(not has_function_privilege('authenticated','private.with_consultation_workflow(jsonb)','execute'),'raw structure helper inaccessible');
rollback;
select 'Consultation workflow SQL checks passed; synthetic fixtures rolled back' as result;
